INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"567fc25e-ead5-5205-9faa-39b0c781a1ff","title":"Mathematics · Grade 11 · Term 2: Circle geometry, coordinates and functions · Set A","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"The angle at the centre of a circle is 100°. What is the angle at the circumference subtended by the same arc?","options":["50°","100°","200°","80°"],"correct_index":0,"explanation":"The angle at the centre is twice the angle at the circumference on the same arc. Divide 100° by 2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the gradient of the line through (1; 2) and (5; 10).","options":["1/2","2","8","4"],"correct_index":1,"explanation":"Gradient = change in y / change in x = (10−2)/(5−1) = 2. Use the same subtraction order in both differences.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Where is the turning point of y = (x − 2)² + 3?","options":["(−2; 3)","(2; −3)","(2; 3)","(0; 3)"],"correct_index":2,"explanation":"In y = a(x−p)²+q the turning point is (p; q). The horizontal shift has the opposite sign to the bracket's constant.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For y = 3/x + 1, which line is a horizontal asymptote?","options":["x = 1","y = 0","x = 0","y = 1"],"correct_index":3,"explanation":"As the magnitude of x grows, 3/x approaches 0, so y approaches 1. x = 0 is the vertical asymptote.","cognitive_level":{"code":"L1","label":"Knowledge","band":"lower"}},{"question":"A parabola has turning point (2;−1) and passes through (0;7). Which equation satisfies both conditions?","options":["y=(x−2)²−1","y=2(x+2)²−1","y=2(x−2)²−1","y=−2(x−2)²−1"],"correct_index":2,"explanation":"Write y=a(x−2)²−1. Substitution gives 7=4a−1, so a=2. The turning-point form and a second condition must both be used.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Circle geometry, coordinates and functions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Circle geometry, coordinates and functions","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"007cd3e5-65d1-5c92-bebd-94c93d83ded6","title":"Mathematics · Grade 11 · Term 3: Trigonometric rules, probability and finance · Set A","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"Two sides of a triangle are 6 cm and 8 cm with included angle 30°. Find its area.","options":["24 cm²","12 cm²","48 cm²","14 cm²"],"correct_index":1,"explanation":"Area = ½ab sin C = ½ × 6 × 8 × ½ = 12 cm². The stated angle must be between the sides used.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A triangle has sides 5 and 7 with included angle 60°. Find the square of the opposite side.","options":["74","109","39","25"],"correct_index":2,"explanation":"Cosine rule: c² = 5²+7²−2(5)(7)cos60° = 74−35 = 39. The question asks for c², not c.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Events A and B are independent with probabilities 0.4 and 0.5. Find P(A and B).","options":["0.90","0.10","0.45","0.20"],"correct_index":3,"explanation":"For independent events multiply: 0.4 × 0.5 = 0.20. Adding instead would not give the intersection.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"An asset of R10 000 depreciates by 10% annually on reducing balance. Value after 2 years?","options":["R8 100","R8 000","R9 000","R12 100"],"correct_index":0,"explanation":"Use 10 000(0.9)² = 8 100. In year two the 10% applies to R9 000, not the original value.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Independent events A and B have probabilities 0.4 and 0.5. A learner calculates P(A or B)=0.9. Which correction explains the error?","options":["Add the overlap 0.2, giving 1.1.","Replace the union with 0.4×0.5=0.2.","Subtract the overlap 0.2, giving 0.7.","Independent means the overlap is zero, so 0.9 is correct."],"correct_index":2,"explanation":"Independence gives P(A and B)=0.4×0.5=0.2; it does not mean mutually exclusive. The addition rule gives 0.4+0.5−0.2=0.7.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Trigonometric rules, probability and finance. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Trigonometric rules, probability and finance","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"c136b2c0-8e26-5b6d-aaf0-32935b348d0c","title":"Mathematics · Grade 11 · Term 4: Patterns and measurement revision · Set A","subject":"Mathematics","grade":"Grade 11","questions":[{"question":"Find the nth term of 2, 6, 12, 20, …","options":["2n²","n² + 2","n² + n","4n − 2"],"correct_index":2,"explanation":"The first differences are 4, 6, 8 and second difference is 2, so the quadratic coefficient is 1. Testing n²+n reproduces every term.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}},{"question":"A cone has radius 3 cm and perpendicular height 4 cm. Find its volume.","options":["36π cm³","16π cm³","9π cm³","12π cm³"],"correct_index":3,"explanation":"V = ⅓πr²h = ⅓π × 9 × 4 = 12π cm³. Slant height is not used for volume.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Simplify √50 in surd form.","options":["5√2","25√2","2√5","10√5"],"correct_index":0,"explanation":"Factor 50 as 25×2, so √50 = √25 × √2 = 5√2. Only a perfect-square factor leaves the root.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Solve x² − 5x + 6 = 0.","options":["x = −2 or x = −3","x = 2 or x = 3","x = 1 or x = 6","x = 2 only"],"correct_index":1,"explanation":"Factor as (x−2)(x−3)=0. Either factor can be zero, giving two solutions.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A cone and cylinder have equal radii. The cone must have the same volume as the cylinder. How must their perpendicular heights compare?","options":["The cone's height must equal the cylinder's.","The cone's height must be one third of the cylinder's.","The cone's height must be three times the cylinder's.","The cone's height must be nine times the cylinder's."],"correct_index":2,"explanation":"Equate ⅓πr²h_cone=πr²h_cylinder. Cancelling the common base area gives h_cone=3h_cylinder; compare formulas rather than the shapes' appearance.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Patterns and measurement revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Patterns and measurement revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=d9piy_Yst2E%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"86539162-89d6-5893-8b56-bc739e19a4d8","title":"Mathematical Literacy · Grade 11 · Term 2: Tax, tariffs and data · Set A","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"For this exercise, VAT is 15%. Find VAT on a price of R200 excluding VAT.","options":["R230","R30","R26.09","R15"],"correct_index":1,"explanation":"VAT = 200×0.15 = R30. Add it for a VAT-inclusive price of R230. Use the rate provided in the question.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A map uses 1:50 000. A route measures 6 cm. Find the actual distance.","options":["30 km","0.3 km","3 km","300 km"],"correct_index":2,"explanation":"6×50 000 = 300 000 cm = 3 000 m = 3 km. Convert units only after applying the scale.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"Find the range of 12, 15, 19, 21, 28.","options":["19","28","12","16"],"correct_index":3,"explanation":"Range = maximum−minimum = 28−12=16. It describes spread, not the central value.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A phone plan charges R100 plus R0.50 per minute. What is the total for 120 minutes?","options":["R160","R60","R220","R100"],"correct_index":0,"explanation":"Variable cost = 120×0.50 = R60. Add the R100 fixed charge to get R160.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A R200 pre-VAT item has a 10% discount before 15% VAT is added. A customer says the total is R205 by subtracting 10% and adding 15% of R200. What is correct?","options":["R205, because both percentages use the original price.","R230, because a discount cannot change VAT.","R207, because VAT applies to the discounted R180.","R180, because VAT is already included."],"correct_index":2,"explanation":"The discount is R20, leaving R180. VAT is 15% of R180, or R27. The final price is R207; the two percentage changes use different bases.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Tax, tariffs and data. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Tax, tariffs and data","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"33da47d2-4456-57e5-a7b6-122da1919314","title":"Mathematical Literacy · Grade 11 · Term 3: Break-even, loans and design drawings · Set A","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"A stall has fixed costs R300, sells items for R20 and spends R5 per item. How many items break even?","options":["15","60","20","12"],"correct_index":2,"explanation":"Each item contributes R20−R5 = R15 towards fixed costs. R300/R15 = 20 items; then total revenue equals total cost.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A loan of R2 000 costs R150 interest and R50 in fees. Find the total repayment.","options":["R2 150","R200","R1 800","R2 200"],"correct_index":3,"explanation":"Add principal, interest and fees: 2 000+150+50 = R2 200. Fees also affect borrowing cost.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A design drawing uses 1:20. A table is 1.6 m long in real life. Find its drawing length in cm.","options":["8 cm","80 cm","32 cm","0.08 cm"],"correct_index":0,"explanation":"Convert 1.6 m to 160 cm, then divide by 20. A reduced drawing is shorter than the real table.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"Actual spending is R3 600; the budget was R3 000. By what percentage did spending exceed the budget?","options":["16.67%","20%","60%","120%"],"correct_index":1,"explanation":"The excess is R600. Divide by the original budget: 600/3 000×100 = 20%, not by actual spending.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A stall's fixed costs are R300, selling price R20 and variable cost R5 per item. It can sell at most 18 items. Which conclusion follows?","options":["It breaks even because revenue exceeds R300.","It makes R60 profit because 18×20−300=60.","It cannot break even; 18 sales leave a R30 loss.","It needs only 15 sales because 300÷20=15."],"correct_index":2,"explanation":"At 18 sales revenue is R360, but costs are R300+R90=R390. The loss is R30. Contribution is R15 per item, requiring 20 sales to break even.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Break-even, loans and design drawings. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Break-even, loans and design drawings","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"d70f4d08-6e80-59e3-b4d6-77bd93d80b94","title":"Mathematical Literacy · Grade 11 · Term 4: Assembly instructions and integrated revision · Set A","subject":"Mathematical Literacy","grade":"Grade 11","questions":[{"question":"An assembly diagram says to attach brace B before tightening bolts C. What is the safest interpretation?","options":["Tighten C fully and ignore B","Guess because order never matters","Use extra parts instead","Fit B first, then tighten C as instructed"],"correct_index":3,"explanation":"The sequence affects fit and stability. Read the full diagram, identify the parts, then follow the specified order.","cognitive_level":{"code":"L1","label":"Knowing","band":"lower"}},{"question":"A box is 30 cm × 20 cm × 10 cm. Find its capacity in litres.","options":["6 L","60 L","600 L","0.6 L"],"correct_index":0,"explanation":"Volume = 6 000 cm³. Since 1 000 cm³ = 1 L, capacity is 6 L.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A shop offers 20% off R450. What do you pay?","options":["R90","R360","R430","R540"],"correct_index":1,"explanation":"Discount = 0.20×450 = R90. Subtract R90 from R450 to get R360; R90 is the saving.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"Two fair coin tosses have outcomes HH, HT, TH, TT. P(exactly one head) = ?","options":["1/4","3/4","1/2","1"],"correct_index":2,"explanation":"HT and TH are two of four equally likely outcomes. The word exactly excludes HH.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A box holds 6 L by its outside dimensions. A buyer needs to store 6 L of liquid and claims it is guaranteed to fit. Which response is justified?","options":["The outside volume always equals usable liquid capacity.","Six litres means the box has a 6 m length.","Check internal capacity and usable space; outside dimensions do not guarantee 6 L storage.","Wall thickness increases internal capacity."],"correct_index":2,"explanation":"Capacity depends on internal dimensions, wall thickness and any necessary headspace. An external-volume calculation alone does not establish usable storage.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Assembly instructions and integrated revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Assembly instructions and integrated revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=EqZ41-tXhWA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"a9af42db-f428-58d2-8859-44bf15ca09e1","title":"Physical Sciences · Grade 11 · Term 2: Electricity and intermolecular forces · Set A","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A 6 Ω resistor carries 2 A. Find the potential difference across it.","options":["3 V","8 V","12 V","0.33 V"],"correct_index":2,"explanation":"Ohm's law gives V=IR=2×6=12 V for an ohmic resistor under constant physical conditions.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A device operates at 12 V and 3 A. Find its electrical power.","options":["4 W","15 W","9 W","36 W"],"correct_index":3,"explanation":"P=VI=12×3=36 W. Power is the rate of energy transfer, measured in watts.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"Which intermolecular force is especially important between water molecules?","options":["Hydrogen bonding","Metallic bonding","Ionic bonding between whole water molecules","Covalent bonding between separate water molecules"],"correct_index":0,"explanation":"Water has H bonded to O and oxygen lone pairs, enabling hydrogen bonds between molecules. O–H covalent bonds are within each molecule.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A coil experiences a larger rate of change of magnetic flux. What happens to the magnitude of induced emf, all else equal?","options":["It necessarily becomes zero","It increases","It decreases to half","It depends only on the coil's colour"],"correct_index":1,"explanation":"Faraday's law relates induced emf magnitude to the rate of change of flux linkage. Faster change gives a larger emf for the same coil.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A learner uses increasingly large currents to test Ohm's law in a metal wire without allowing it to cool. Which limitation matters most?","options":["Current cannot be measured in a wire.","Potential difference is always independent of current.","Heating changes resistance, so physical conditions are not constant.","A wire's colour alone controls the result."],"correct_index":2,"explanation":"Ohm's law requires constant physical conditions. Increased current can heat the wire and alter its resistance, confounding a comparison intended to test V proportional to I.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Electricity and intermolecular forces. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Electricity and intermolecular forces","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"37aabd15-25f2-5cd0-a558-71e5e349d0d3","title":"Physical Sciences · Grade 11 · Term 3: Stoichiometry, gases and energy change · Set A","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"A sample has mass 8 g and molar mass 16 g·mol⁻¹. Find its amount of substance.","options":["2 mol","128 mol","24 mol","0.5 mol"],"correct_index":3,"explanation":"n=m/M=8/16=0.5 mol. Dividing by molar mass cancels grams and leaves moles.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"For 2H₂ + O₂ → 2H₂O, how many moles of O₂ react with 6 mol H₂, with enough O₂ available?","options":["3 mol","6 mol","12 mol","2 mol"],"correct_index":0,"explanation":"The mole ratio H₂:O₂ is 2:1, so 6 mol H₂ needs 6/2=3 mol O₂. Coefficients describe mole ratios, not gram ratios.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A fixed amount of gas occupies 4 L at 100 kPa. At constant temperature, find its volume at 200 kPa.","options":["8 L","2 L","4 L","0.5 L"],"correct_index":1,"explanation":"Boyle's law: P₁V₁=P₂V₂. V₂=100×4/200=2 L. Doubling pressure halves volume at constant temperature.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"In an exothermic reaction, how does the enthalpy of products compare with reactants?","options":["It is higher, so ΔH is positive","It must be exactly equal","It is lower, so ΔH is negative","It cannot be compared"],"correct_index":2,"explanation":"Energy is released to surroundings. ΔH=H(products)−H(reactants) is negative because products have lower enthalpy.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A sealed gas sample is compressed from 4 L to 2 L while warming. A learner uses Boyle's law to assert its pressure exactly doubles. What is missing?","options":["The gas container's paint colour.","The assertion is exact at every temperature.","The temperature change; Boyle's law alone requires constant temperature.","Compression means the number of molecules must halve."],"correct_index":2,"explanation":"For a fixed amount of gas, PV/T is constant in the ideal model. Pressure also depends on absolute temperature; warming means the constant-temperature doubling claim is unjustified.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Stoichiometry, gases and energy change. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Stoichiometry, gases and energy change","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"83f2241c-c11c-5102-b00c-6f408ab8d4dd","title":"Physical Sciences · Grade 11 · Term 4: Acid–base and redox reactions · Set A","subject":"Physical Sciences","grade":"Grade 11","questions":[{"question":"In the Brønsted–Lowry model, an acid is a…","options":["Proton donor","Proton acceptor","Neutron donor","Substance that always contains oxygen"],"correct_index":0,"explanation":"A Brønsted–Lowry acid donates H⁺. A base accepts H⁺, so identify the proton transfer in the reaction.","cognitive_level":{"code":"L1","label":"Recall","band":"lower"}},{"question":"For Zn → Zn²⁺ + 2e⁻, what happens to zinc?","options":["It is reduced by losing electrons","It is oxidised by losing electrons","It gains two electrons","Its oxidation number decreases"],"correct_index":1,"explanation":"Oxidation is loss of electrons. Zinc's oxidation number rises from 0 to +2.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"Which equation shows neutralisation of HCl by NaOH?","options":["HCl + NaOH → H₂ + NaClO","HCl + NaOH → Na + Cl + O₂","HCl + NaOH → NaCl + H₂O","HCl + NaOH → NaCl only"],"correct_index":2,"explanation":"The acid and base produce salt and water. Check that hydrogen and oxygen atoms are conserved as well as sodium and chlorine.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A solution contains 0.2 mol solute in 0.5 dm³. Find its concentration.","options":["0.1 mol·dm⁻³","2.5 mol·dm⁻³","0.7 mol·dm⁻³","0.4 mol·dm⁻³"],"correct_index":3,"explanation":"c=n/V=0.2/0.5=0.4 mol·dm⁻³. Use volume in dm³, not an unconverted millilitre value.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A learner dilutes 100 mL of 0.4 mol·dm⁻³ solution to a final volume of 400 mL and claims the moles become one quarter. Which correction is right?","options":["Moles become 0.01 mol; concentration stays 0.4 mol·dm⁻³.","Both moles and concentration remain unchanged.","Moles remain 0.04 mol; concentration becomes 0.1 mol·dm⁻³.","Adding water creates additional solute moles."],"correct_index":2,"explanation":"Initial moles are 0.4×0.100=0.04 mol. Without loss or reaction, dilution changes volume, not solute amount. Final concentration is 0.04/0.400=0.1 mol·dm⁻³.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Acid–base and redox reactions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Acid–base and redox reactions","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lm60Fp2hw9Y%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"2646f0b2-93c0-5c2a-86ca-98b31592e33d","title":"Life Sciences · Grade 11 · Term 2: Photosynthesis, respiration and nutrition · Set A","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Which gas is taken in as a raw material for photosynthesis?","options":["Oxygen","Nitrogen only","Hydrogen","Carbon dioxide"],"correct_index":3,"explanation":"Photosynthesis uses carbon dioxide and water to produce organic compounds using light energy. Oxygen is released as a by-product.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why does increasing light eventually stop increasing photosynthesis rate in a healthy plant?","options":["Another factor, such as CO₂ or temperature, becomes limiting","Light ceases to contain energy","The plant stops needing glucose permanently","Water is no longer needed"],"correct_index":0,"explanation":"Once light is no longer limiting, another required factor limits the rate. Experiments should keep other conditions controlled.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"What is the main purpose of cellular respiration?","options":["To create sunlight","To transfer energy from organic molecules into ATP","To absorb food without enzymes","To remove every oxygen atom from the body"],"correct_index":1,"explanation":"Respiration releases energy through reactions and captures some in ATP, which powers cellular processes. It is not the same as breathing.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Where does most absorption of digested nutrients occur in humans?","options":["Oesophagus","Large intestine only","Small intestine","Stomach only"],"correct_index":2,"explanation":"The small intestine has villi and microvilli that increase surface area for absorption of digested nutrients.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"A plant produces 10 bubbles per minute at low light and 10 at high light. Which next test best investigates a possible limiting factor?","options":["Change light, CO₂ and temperature together without controls.","Conclude light never affects photosynthesis in any plant.","Increase available CO₂ at high light while controlling temperature and other conditions.","Count bubbles once and call it conclusive."],"correct_index":2,"explanation":"A plateau may reflect a different limiting factor. Changing CO₂ while holding other conditions constant tests that explanation; repeat measurements because bubble counts are only an approximate rate indicator.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Photosynthesis, respiration and nutrition. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Photosynthesis, respiration and nutrition","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"92e835f9-aa9e-5d28-82d7-7db4eb99e445","title":"Life Sciences · Grade 11 · Term 3: Gas exchange, excretion and populations · Set A","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"Why are alveolar walls thin and moist?","options":["To support rapid diffusion of gases","To prevent all gas movement","To produce urine","To store solid food"],"correct_index":0,"explanation":"A thin surface shortens diffusion distance; moisture allows gases to dissolve before diffusing across the exchange surface.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which organ removes urea from the blood and helps regulate water balance?","options":["Stomach","Kidney","Heart","Pancreas only"],"correct_index":1,"explanation":"Kidneys filter blood and form urine, removing nitrogenous wastes and regulating water and salts. The liver produces urea from excess amino nitrogen.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"What happens when ADH secretion increases in a healthy person?","options":["Less water is reabsorbed and all urine stops","Blood sugar always doubles","More water is reabsorbed, usually producing a smaller volume of more concentrated urine","No kidney response is possible"],"correct_index":2,"explanation":"ADH increases water reabsorption in the kidney, generally reducing urine volume and making it more concentrated. Distinguish urine volume from concentration.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A population gains 30 births and 10 immigrants, with 20 deaths and 5 emigrants. Find its net change.","options":["Increase of 45","Decrease of 15","Increase of 65","Increase of 15"],"correct_index":3,"explanation":"Change = births+immigration−deaths−emigration = 30+10−20−5 = +15 individuals.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"A population rises by 15 after 30 births, 20 deaths, 10 immigrants and 5 emigrants. Which prediction about next year is warranted?","options":["It must rise by exactly 15 every year.","Births alone guarantee a rise of 30.","No exact prediction follows without next year's rates and conditions.","Immigration proves deaths will stop."],"correct_index":2,"explanation":"The net change describes one interval: 30+10−20−5=15. Future births, deaths, migration and resource limits may differ, so extrapolating the same change as a certainty is unjustified.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Gas exchange, excretion and populations. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Gas exchange, excretion and populations","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"86b1a333-88c1-5567-bcce-141f843e1737","title":"Life Sciences · Grade 11 · Term 4: Human impact and environmental evidence · Set A","subject":"Life Sciences","grade":"Grade 11","questions":[{"question":"How can excess fertiliser entering a dam harm aquatic life?","options":["It permanently increases oxygen in all depths","It can cause algal growth and oxygen depletion during decomposition","It stops all biological activity immediately","It turns fresh water directly into salt water"],"correct_index":1,"explanation":"Nutrient enrichment can cause eutrophication. Decomposers use dissolved oxygen as excess organic material breaks down, threatening aquatic organisms.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Why does destroying wetlands threaten water quality?","options":["Wetlands have no role in water movement","Wetlands create all pollutants","Wetlands can trap sediments and help filter pollutants","Wetlands prevent every flood regardless of size"],"correct_index":2,"explanation":"Wetlands provide important filtration and flow-regulation services. Their protection reduces risks, although it cannot eliminate all pollution or flooding.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which action most directly lowers a school's electricity-related carbon footprint when electricity comes from fossil fuels?","options":["Leave empty classrooms fully lit","Burn litter behind the classroom","Replace every indigenous tree with concrete","Reduce unnecessary electricity consumption"],"correct_index":3,"explanation":"Using less fossil-fuel-generated electricity reduces associated emissions. Measure energy use to assess whether the intervention works.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"A study links habitat fragmentation to falling species numbers. What strengthens its conclusion?","options":["Compare repeated data from fragmented and less-fragmented sites while considering other causes","Use only a single photograph","Ignore differences in sampling effort","Assume correlation proves the only cause"],"correct_index":0,"explanation":"Repeated comparable observations and consideration of confounding factors support stronger evidence. A single correlation is not proof of sole causation.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}},{"question":"A dam has an algal bloom followed by fish deaths. Which evidence most directly tests oxygen depletion during decomposition?","options":["Only the colour of a poster about the dam.","A count of fish species with no water measurements.","Dissolved-oxygen measurements over time, compared with less-affected water and decomposition indicators.","An assumption that all algae directly poison every fish."],"correct_index":2,"explanation":"Tracking oxygen decline alongside organic decay tests the proposed mechanism. Comparison water and repeated measurements help distinguish it from other causes such as a toxic discharge.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Human impact and environmental evidence. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Human impact and environmental evidence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=bj82jNMC2qg%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"87be3bbb-d6b4-5f83-92c6-9c915ea77a71","title":"Accounting · Grade 11 · Term 2: Partnership statements and analysis · Set A","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A partnership earns R90 000 before appropriations. Partner salaries total R30 000; no other appropriations apply. Find residual profit.","options":["R60 000","R120 000","R30 000","R90 000"],"correct_index":0,"explanation":"Residual profit = profit available−partner salaries−other appropriations. Here 90 000−30 000=R60 000, shared using the agreed ratio.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Residual profit of R60 000 is shared A:B = 2:1. What is B's share?","options":["R40 000","R20 000","R30 000","R60 000"],"correct_index":1,"explanation":"The ratio has three parts. B receives one part: 60 000/3 = R20 000. Do not divide by B's ratio number alone.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business has current assets R120 000 including stock R40 000, and current liabilities R50 000. Find the acid-test ratio.","options":["2.4:1","0.8:1","1.6:1","3.2:1"],"correct_index":2,"explanation":"Acid-test ratio = (current assets−inventory)/current liabilities = (120 000−40 000)/50 000 = 1.6:1.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why compare a partnership's financial indicators with prior years?","options":["To prove future profit is guaranteed","To avoid reading the financial statements","To ignore different business conditions","To identify trends and investigate performance changes"],"correct_index":3,"explanation":"Comparisons help interpret performance, but context such as changing prices, policies and business conditions still matters.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A partnership's profit rises but its acid-test ratio falls from 1.6:1 to 0.7:1. Which conclusion is justified?","options":["Higher profit proves all short-term debts are affordable.","A falling acid-test ratio proves theft occurred.","Profitability improved, but short-term liquidity needs separate investigation.","Profit and cash availability are always identical."],"correct_index":2,"explanation":"Profit is measured on an accrual basis, while the acid-test ratio compares more liquid assets with current liabilities. Examine cash flows, debtor collections and payment dates before deciding on action.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Partnership statements and analysis. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Partnership statements and analysis","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"12c679fe-0bd6-5ee2-bfa4-169f11be60ee","title":"Accounting · Grade 11 · Term 3: Budgets, inventory and manufacturing · Set A","subject":"Accounting","grade":"Grade 11","questions":[{"question":"A cash sale of R500 occurs in March. Where does it appear in the cash budget?","options":["April receipts automatically","March receipts","March payments","Nowhere because sales are not cash"],"correct_index":1,"explanation":"A cash budget records the timing of actual cash movements. A cash sale is received in March; credit collections need a collection schedule.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A business expects 60% of credit sales of R20 000 to be collected next month. Find that collection.","options":["R8 000","R20 000","R12 000","R32 000"],"correct_index":2,"explanation":"Multiply credit sales by the collection proportion: 20 000×0.60=R12 000. The rest is collected later or subject to other assumptions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Fixed costs are R30 000; selling price is R50 per unit and variable cost R20. Find break-even units.","options":["600","1 500","10 000","1 000"],"correct_index":3,"explanation":"Contribution per unit = 50−20=R30. Break-even = fixed costs/contribution = 30 000/30 = 1 000 units.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which statement distinguishes perpetual from periodic inventory?","options":["Perpetual records continuously update stock and cost of sales; periodic calculates cost of sales at intervals","Periodic means stock is never counted","Perpetual means stock cannot be stolen","Both systems forbid stocktaking"],"correct_index":0,"explanation":"The systems differ in recording timing. Physical stocktaking remains useful for verifying balances and identifying losses.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A business forecasts R12 000 collections next month from R20 000 credit sales. Debtor payment delays are increasing. What is the best budget response?","options":["Keep the forecast unchanged because a policy guarantees payment.","Record all R20 000 as cash received immediately.","Test lower or later collections and plan for possible funding needs.","Remove all sales from the income statement."],"correct_index":2,"explanation":"A collection policy is an estimate, not a guarantee. Actual debtor behaviour informs a more realistic timing forecast; sensitivity checks show the cash effect of delayed or reduced receipts.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Budgets, inventory and manufacturing. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Budgets, inventory and manufacturing","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"55063958-fd0c-52ba-8f98-ff06377d6c13","title":"Accounting · Grade 11 · Term 4: VAT and accounting revision · Set A","subject":"Accounting","grade":"Grade 11","questions":[{"question":"For this exercise VAT is 15%. A cash sale of R1 000 excluding VAT creates output VAT of…","options":["R1 150","R130.43","R150","R15"],"correct_index":2,"explanation":"Output VAT is charged on taxable sales: 1 000×0.15=R150. The VAT-inclusive receipt is R1 150.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Output VAT is R9 000 and deductible input VAT R6 500. Find the net VAT payable.","options":["R15 500","R6 500","R9 000","R2 500"],"correct_index":3,"explanation":"Net VAT payable = output−deductible input = R2 500. If deductible input exceeded output, the position would instead be receivable, subject to rules.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"For this exercise VAT is 15%. Extract VAT from a VAT-inclusive amount of R230.","options":["R30","R34.50","R200","R15"],"correct_index":0,"explanation":"VAT = inclusive amount×15/115 = 230×15/115 = R30. Taking 15% of the inclusive total uses the wrong base.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why keep a valid tax invoice for a purchase?","options":["It guarantees every expense is deductible","It supports the accounting record and any qualifying input-VAT claim","It replaces the need to pay the supplier","It allows any invented VAT claim"],"correct_index":1,"explanation":"Reliable documentation supports verification. Input VAT is subject to qualifying rules, so an invoice alone does not make every purchase claimable.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A VAT return includes an input claim supported only by a handwritten total with no valid tax invoice. What should the accountant do?","options":["Claim it automatically because any total proves eligibility.","Create an invoice in the supplier's name without authorisation.","Verify eligibility and obtain the required evidence before including the claim.","Increase output VAT to hide the unsupported claim."],"correct_index":2,"explanation":"An input-VAT claim needs qualifying expenditure and supporting documentation under applicable rules. Investigate and obtain valid evidence rather than fabricate records or assume every purchase qualifies.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: VAT and accounting revision. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"VAT and accounting revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=qxPOjU7FXcA%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}}]$smartbridge$::jsonb)
